-- ~/.config/hypr/general.lua
-- Look, feel and input.
-- Colours come from colors.lua (generated by scripts/theme.sh); no hex values here.
local C = require("colors")

hl.config({
    general = {
        gaps_in  = 2,
        gaps_out = 4,
        border_size = 1,
        col = {
            active_border   = C.rgba(C.accent),
            inactive_border = C.rgba(C.border),
        },
        layout = "dwindle",
        resize_on_border = true,

        -- Needed for the `immediate` rule on games (windowrules.lua).
        allow_tearing = true,
    },

    decoration = {
        rounding = 2,   -- 0 leaves aliased, ragged corners

        blur = {
            enabled = true,
            size    = 8,
            passes  = 2,
            new_optimizations = true,
        },

        shadow = {
            enabled = false,
        },
    },

    animations = {
        enabled = true,
    },

    dwindle = {
        preserve_split = true,
    },

    input = {
        -- Norwegian plus a symbol layer on the < > key; see xkb/README.md.
        kb_layout    = "nosym",
        kb_options   = "lv5:lsgt_switch",
        follow_mouse = 1,

        accel_profile = "flat",   -- no acceleration
        sensitivity   = 0,
    },

    misc = {
        disable_hyprland_logo   = true,
        force_default_wallpaper = 0,
    },
})

-- waybar is translucent; blur keeps its text readable over the wallpaper.
hl.layer_rule({ name = "blur-waybar", match = { namespace = "^waybar$" }, blur = true })

hl.curve("snappy", { type = "bezier", points = { { 0.1, 0.9 }, { 0.1, 1 } } })

hl.animation({ leaf = "windows",    enabled = true, speed = 2, bezier = "snappy" })
hl.animation({ leaf = "fade",       enabled = true, speed = 2, bezier = "snappy" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 2, bezier = "snappy" })
hl.animation({ leaf = "border",     enabled = true, speed = 2, bezier = "snappy" })

-- qt6ct is pointed at the generated palette by install-themes.sh.
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")

hl.env("HYPRSHOT_DIR", os.getenv("HOME") .. "/Pictures/screenshots")
